-- T069 of specs/004-sessions/tasks.md (B42a; SRS DEC-66 and DEC-67; spec FR-502, FR-503, FR-505
-- and FR-508; data-model.md §2.13 and §6; ERD v1.15, changelog rows 36 to 44). Generated by `prisma
-- migrate diff --from-config-datasource --to-schema prisma/schema --script` against a database
-- holding every migration before it, then extended by hand with what the schema language cannot
-- say: the checks, the two partial indexes and the settings step.
--
-- What it lands: `users.banned_at` and rule 50 (a ban's instant only on a banned account; no
-- backfill, the app has never launched); `enrollments.slot_released_at` (an administrator's release
-- of a held slot, T070); `teacher_profiles.kept_at`, `kept_erase_at` and `kept_erased_at` (a
-- deleted teacher's kept data, T076, T077) and `verification_status_before_ban` and
-- `application_status_before_ban` (written by every ban, cleared by its lift, T072);
-- `verification_documents.kept_at`, with rule 34 widened (never both `kept_at` and `erased_at`);
-- rule 27 widened (the payout hash unique among the profiles not kept, Q-E (a)); the enum values
-- `slot_released` and `slot_hold_ended`; the partial index the hourly sweep reads every held
-- closing through (T074; DEC-69); rule 49 widened to a closed `teacher_suspended` case (T071); and
-- `enrollment_restore_window_days` moved from 7 to 14 where its row still holds 7 (Q6 (b)).
--
-- Every new column is NULL on every existing row, which each new check admits; rule 27 and rule
-- 49 only relax. So nothing a check would refuse exists before it runs (the read-only count on
-- `ijazah` of 2026-11-13 found 0 such rows, the note under T069; counted again before `ijazah` is
-- migrated, Q1 (a)).
--
-- WHY A COMMIT AFTER THE ENUM VALUES. As in `20261108120000_sessions_pass` (its lines 19 to 31):
-- PostgreSQL refuses a value added by `ALTER TYPE ... ADD VALUE` in the transaction that added it
-- until that transaction commits, and the script runs as one implicit transaction. So the values
-- are committed first, each `IF NOT EXISTS`, and the rest runs in a second one: if the second part
-- is ever refused, the migration is marked rolled back and the whole script runs again unchanged.

-- AlterEnum
ALTER TYPE "enrollment_event_kind" ADD VALUE IF NOT EXISTS 'slot_released';
ALTER TYPE "enrollment_event_kind" ADD VALUE IF NOT EXISTS 'slot_hold_ended';

-- The values above are committed before the statements below run (see the header).
COMMIT;

-- AlterTable
ALTER TABLE "enrollments" ADD COLUMN     "slot_released_at" TIMESTAMPTZ(6);

-- AlterTable
ALTER TABLE "teacher_profiles" ADD COLUMN     "application_status_before_ban" "teacher_application_status",
ADD COLUMN     "kept_at" TIMESTAMPTZ(6),
ADD COLUMN     "kept_erase_at" TIMESTAMPTZ(6),
ADD COLUMN     "kept_erased_at" TIMESTAMPTZ(6),
ADD COLUMN     "verification_status_before_ban" "teacher_verification_status";

-- AlterTable
ALTER TABLE "users" ADD COLUMN     "banned_at" TIMESTAMPTZ(6);

-- AlterTable
ALTER TABLE "verification_documents" ADD COLUMN     "kept_at" TIMESTAMPTZ(6);

-- Hand-written: what the schema language cannot say (data-model.md §2.13, ERD §14 and §15).

-- Rule 50: a ban's instant only on a banned account. Every ban writes it and its lift clears it
-- (T072), so it is the instant of the ban in force.
ALTER TABLE "users" ADD CONSTRAINT "users_banned_at_check"
    CHECK ("banned_at" IS NULL OR "account_status" = 'banned');

-- Rule 34, widened: a document is kept or erased, never both. Its first check stands unchanged
-- (`verification_documents_erased_key_check`: a key is cleared only once erased), so a kept
-- document holds its key. That every document of a deleted person holding a key is kept or erased
-- spans `users` and is held by the deletion and its spec, not by a check.
ALTER TABLE "verification_documents" ADD CONSTRAINT "verification_documents_kept_or_erased_check"
    CHECK ("kept_at" IS NULL OR "erased_at" IS NULL);

-- Rule 27, widened (Q-E (a)): the payout hash binds the live accounts only, so a new account may
-- register the payout account a deleted teacher's kept profile holds.
DROP INDEX "teacher_profiles_payout_account_ref_hash_key";
CREATE UNIQUE INDEX "teacher_profiles_payout_account_ref_hash_key" ON "teacher_profiles"("payout_account_ref_hash") WHERE "kept_at" IS NULL;

-- ERD §14: every held closing (DEC-69), none a deletion or a gender correction ended; the hourly
-- sweep (T074) reads it a page at a time in id order.
CREATE INDEX "enrollments_held_closing_idx" ON "enrollments"("id")
    WHERE "confirmed_at" IS NOT NULL
      AND ("status" = 'terminated_no_show'
        OR ("status" = 'cancelled' AND "cancellation_reason" IN ('admin', 'teacher_suspended')));

-- Rule 49, widened (T071): the link also on a closed `teacher_suspended` case; the rest unchanged.
ALTER TABLE "disputes" DROP CONSTRAINT "disputes_covered_by_check";
ALTER TABLE "disputes" ADD CONSTRAINT "disputes_covered_by_check"
    CHECK ("covered_by_case_id" IS NULL
        OR ("kind" = 'compensation_case' AND "reason" IN ('student_suspended', 'teacher_suspended')
            AND "status" <> 'open' AND "covered_by_case_id" <> "id"));

-- The restore window's default moves from 7 to 14 days (SRS DEC-66, Q6 (b)), only where its row
-- still holds the old default: a value an administrator chose is left alone, and a database never
-- seeded gets the row from the seed. The row's `updated_by_admin_id` and `updated_at` stay as they
-- were.
UPDATE "settings" SET "value" = '14'::jsonb
 WHERE "key" = 'enrollment_restore_window_days' AND "value" = '7'::jsonb;
